package com.cyledger.android;
import android.app.*;import android.content.*;import java.util.*;
public final class DailyReminderReceiver extends BroadcastReceiver {
 static PendingIntent alarm(Context context){return PendingIntent.getBroadcast(context,811,new Intent(context,DailyReminderReceiver.class).setAction("com.cyledger.android.RECORD"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void schedule(Context context){AlarmManager manager=context.getSystemService(AlarmManager.class);manager.cancel(alarm(context));String text=context.getSharedPreferences("local_settings",0).getString("reminder","");if(text.isEmpty())return;try{String[] parts=text.split(":");Calendar at=Calendar.getInstance();at.set(Calendar.HOUR_OF_DAY,Integer.parseInt(parts[0]));at.set(Calendar.MINUTE,Integer.parseInt(parts[1]));at.set(Calendar.SECOND,0);at.set(Calendar.MILLISECOND,0);if(at.getTimeInMillis()<=System.currentTimeMillis())at.add(Calendar.DATE,1);manager.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at.getTimeInMillis(),alarm(context));}catch(Exception ignored){}}
 @Override public void onReceive(Context context,Intent intent){if("com.cyledger.android.RECORD".equals(intent.getAction())){NotificationManager manager=context.getSystemService(NotificationManager.class);if(manager.areNotificationsEnabled()){manager.createNotificationChannel(new NotificationChannel("record_reminder","记账提醒",NotificationManager.IMPORTANCE_DEFAULT));Intent open=new Intent(context,MainActivity.class).putExtra("quickEntry",true).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent action=PendingIntent.getActivity(context,812,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);manager.notify(811,new Notification.Builder(context,"record_reminder").setSmallIcon(android.R.drawable.ic_input_add).setContentTitle("记一笔今天的收支").setContentText("把今天的账记下来").setVisibility(Notification.VISIBILITY_PRIVATE).setAutoCancel(true).setContentIntent(action).build());}}schedule(context);}
}
